from functools import partial
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import pytest

def test_partial_callable_class():
    class MyDependency:
        def __init__(self, value: str):
            self.value = value
        def __call__(self, q: str = None):
            return f"{self.value}-{q}"

    dep = MyDependency("fixed")
    partial_dep = partial(dep, q="fixed-q")

    app = FastAPI()

    @app.get("/")
    def root(res = Depends(partial_dep)):
        return {"res": res}

    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"res": "fixed-fixed-q"}

def test_partial_async_callable_class():
    class MyAsyncDependency:
        def __init__(self, value: str):
            self.value = value
        async def __call__(self, q: str = None):
            return f"{self.value}-{q}"

    dep = MyAsyncDependency("fixed")
    partial_dep = partial(dep, q="fixed-q")

    app = FastAPI()

    @app.get("/")
    async def root(res = Depends(partial_dep)):
        return {"res": res}

    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"res": "fixed-fixed-q"}

def test_partial_async_function():
    async def my_async_dep(q: str = None, value: str = "default"):
        return f"{value}-{q}"

    partial_dep = partial(my_async_dep, value="fixed")

    app = FastAPI()

    @app.get("/")
    async def root(res = Depends(partial_dep)):
        return {"res": res}

    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"res": "fixed-None"} # q is None by default

if __name__ == "__main__":
    test_partial_callable_class()
    test_partial_async_callable_class()
    test_partial_async_function()
    print("All tests passed!")

