import asyncio
from functools import partial
from fastapi import FastAPI, Depends
from starlette.testclient import TestClient

async def async_dep():
    return "async_dep"

class AsyncCallableClassWithArg:
    def __init__(self, arg):
        self.arg = arg
    async def __call__(self):
        return f"async_callable_class_{self.arg}"

app = FastAPI()

@app.get("/async_func")
async def route_async_func(dep=Depends(partial(async_dep))):
    return {"dep": dep}

@app.get("/async_class_partial")
async def route_async_class_partial(dep=Depends(partial(AsyncCallableClassWithArg(arg=1)))):
    return {"dep": dep}

client = TestClient(app)

def test_async_func():
    response = client.get("/async_func")
    assert response.status_code == 200
    assert response.json() == {"dep": "async_dep"}

def test_async_class_partial():
    response = client.get("/async_class_partial")
    assert response.status_code == 200
    assert response.json() == {"dep": "async_callable_class_1"}

if __name__ == "__main__":
    try:
        test_async_func()
        print("test_async_func passed")
        test_async_class_partial()
        print("test_async_class_partial passed")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

